flowchart TD
  start(["Início: Resolução Reversa (FCC)"]) --> proc_iniciar["Iniciar pela alternativa E (E -> D -> C -> B -> A)"]
  proc_iniciar --> dec_crase{"Gatilho 1: Há crase antes de 'quem' (ex: 'à quem')?"}
  dec_crase -- "Sim (Erro)" --> res_desc_crase["Descarte Imediato: Crase proibida antes de 'quem'"]
  dec_crase -- "Não" --> dec_onde{"Gatilho 2: 'Onde/aonde' refere-se a termo abstrato?"}
  dec_onde -- "Sim (Erro)" --> res_desc_onde["Descarte Imediato: 'Onde' restrito a espaço físico"]
  dec_onde -- "Não" --> dec_cujo{"Gatilho 3: 'Cujo' antes de verbo, pronome ou artigo?"}
  dec_cujo -- "Sim (Erro)" --> res_desc_cujo["Descarte Imediato: 'Cujo' exige substantivo subsequente"]
  dec_cujo -- "Não" --> dec_vtd{"Gatilho 4: Há 'de que' acoplado a VTD posterior?"}
  dec_vtd -- "Sim (Erro)" --> res_desc_regencia["Descarte Imediato: VTD não admite preposição"]
  dec_vtd -- "Não (Livre de gatilhos)" --> proc_validar["Confirmar exatidão gramatical de ambos os termos"]
  proc_validar --> res_gabarito["Gabarito Validado: Assinalar Alternativa Correta"]
